        #toolbar { position: fixed; top: 10px; left: 10px; right: 10px; z-index: 100; display: flex; gap: 10px; flex-wrap: wrap; padding: 10px; background: rgba(13, 17, 23, 0.95); border-radius: 8px; border: 1px solid #30363d; backdrop-filter: blur(10px); }
        .btn { background: #21262d; border: 1px solid #30363d; color: #e6edf3; padding: 8px 16px; border-radius: 6px; cursor: pointer; font-size: 13px; transition: all 0.2s; display: flex; align-items: center; gap: 6px; }
        .btn:hover { background: #30363d; border-color: #58a6ff; }
        .btn.active { background: #238636; border-color: #238636; }
        .btn:disabled { opacity: 0.5; cursor: not-allowed; }
        .search-box { flex: 1; max-width: 400px; min-width: 200px; }
        .search-box input { width: 100%; background: #0d1117; border: 1px solid #30363d; color: #e6edf3; padding: 8px 12px; border-radius: 6px; font-size: 13px; }
        .search-box input:focus { outline: none; border-color: #58a6ff; }
        .filter-group { display: flex; gap: 8px; align-items: center; }
        .filter-group select { background: #21262d; border: 1px solid #30363d; color: #e6edf3; padding: 6px 12px; border-radius: 6px; font-size: 13px; }
        #cy { width: 100%; height: 100vh; }
        #sidebar { position: fixed; right: 0; top: 0; width: 380px; height: 100vh; background: #161b22; border-left: 1px solid #30363d; padding: 20px; overflow-y: auto; z-index: 50; transform: translateX(100%); transition: transform 0.3s ease; }
        .sidebar.open { transform: translateX(0); }
        .sidebar-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid #30363d; }
        .sidebar-title { font-size: 16px; font-weight: 600; }
        .close-btn { background: none; border: none; color: #8b949e; font-size: 20px; cursor: pointer; }
        .node-info { display: none; }
        .node-info.visible { display: block; animation: slideIn 0.2s ease; }
        @keyframes slideIn { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: translateX(0); } }
        .info-row { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #21262d; }
        .info-label { color: #8b949e; font-size: 12px; }
